1	// Fresh-path wiring convergence (agent-preprocessing DESIGN §7, the primitive
2	// absorbed from #405). The deterministic half of baselining's self-refresh that
3	// has nothing to do with the vendored mount's CONTENT: the repo-specific wiring a
4	// scheduled Claudinite consumer must carry, converged idempotently in code so the
5	// nightly refresh never needs a model to re-enact bootstrap's prose.
6	//
7	// One source of truth: bootstrap Part 5 (the settings hooks) + Part 6 (the
8	// scheduler workflow) describe this same set for a fresh adoption; this module is
9	// what both bootstrap and baselining CALL, so the wiring can never drift between
10	// "how a repo is set up" and "how the nightly keeps it set up".
11	//
12	// Operates on a repo working tree at `root` with node:fs directly (like
13	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
14	// repo already converged produces an empty change list.
15	
16	import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
17	import { join, dirname, relative } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { hashedCron } from './hash-minute.mjs';
20	
21	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
22	// Ensured present without clobbering — a set-union keyed on the command string, so
23	// a repo's own extra hooks and any hand-added entries survive untouched.
24	export const REQUIRED_HOOKS = [
25	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
26	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
27	  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
28	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
29	];
30	
31	export const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';
32	export const SETTINGS_PATH = '.claude/settings.json';
33	export const CLAUDE_MD = 'CLAUDE.md';
34	export const CHECKS_PATH = '.claudinite-checks.json';
35	export const README = 'README.md';
36	
37	// The pack-badge row: the marks of the packs this repo declares, on a single
38	// line of its README. Adopting Claudinite is what puts the row there and the nightly is
39	// what keeps it true — a hand-written row goes stale the day the repo declares
40	// its next pack, which is exactly the class of upkeep this module exists to take
41	// off a maintainer.
42	//
43	// Delimited by HTML comments rather than located by position, so the row can be
44	// re-converged in place wherever the repo has moved it, and so anything the repo
45	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
46	// its own and survives untouched — which is why the CLOSING marker stays inline,
47	// at the end of the badges' own line.
48	//
49	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
50	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
51	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
52	// after the opening marker on one line and a README renders the literal text
53	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
54	// block at the marker, so the badges start a paragraph and parse as markdown.
55	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
56	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
57	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
58	
59	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
60	// The whole line (and its trailing newline) is removed wherever it appears.
61	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
62	
63	// The project's settings, loaded through the one reader that validates them.
64	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
65	// so the cross-tree import stays a single, reviewable edge.
66	const repoConfig = async (root) => (await import('../checks/helpers/repo-context.mjs')).loadConfig(root);
67	
68	// The repo Actions secrets its scheduled tasks declare via `required_secrets`,
69	// deduped and sorted. Async because task discovery is; pure otherwise.
70	export async function declaredSecrets(root, config) {
71	  const { discoverTasks } = await import('./discover.mjs');
72	  const { tasks } = await discoverTasks(root, config);
73	  return [...new Set(tasks.flatMap((t) => t.decl?.required_secrets ?? []))].sort();
74	}
75	
76	// Stamp the declared secrets into the scheduler workflow's engine step, beside
77	// GITHUB_TOKEN. This is the whole delivery mechanism: GitHub Actions requires each
78	// secret to be named statically in the workflow, and a task's `required_secrets` is
79	// exactly that list — so the wiring converge writes it, and a worker then reads
80	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
81	// no engine-side selection. Regenerated from the stub each converge, so the list
82	// tracks the declarations rather than accumulating.
83	export function withDeclaredSecrets(stubText, names = []) {
84	  if (!names.length) return stubText;
85	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
86	  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
87	}
88	
89	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
90	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
91	// function of the full name, so re-vendors and this convergence agree) and the
92	// declared `required_secrets` stamped into the engine step's env. `stubText` is the
93	// vendored stub's content (the caller reads it from the mount). Returns true when
94	// the file was written (absent, or drifted from the target).
95	export function convergeSchedulerWorkflow(root, fullName, stubText, secretNames = []) {
96	  const target = withDeclaredSecrets(stubText, secretNames)
97	    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
98	  const path = join(root, SCHEDULER_WORKFLOW);
99	  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
100	  if (current === target) return false;
101	  mkdirSync(dirname(path), { recursive: true });
102	  writeFileSync(path, target);
103	  return true;
104	}
105	
106	// Ensure the required settings hooks are present (add-if-missing, never clobber).
107	// Returns { added: [labels], error? }. A malformed settings file is reported, never
108	// overwritten (the transactional stance — surface it, don't destroy hand config).
109	export function ensureHooks(root) {
110	  const path = join(root, SETTINGS_PATH);
111	  let settings = {};
112	  if (existsSync(path)) {
113	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
114	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
115	  }
116	  settings.hooks ??= {};
117	  const added = [];
118	  for (const h of REQUIRED_HOOKS) {
119	    const list = (settings.hooks[h.event] ??= []);
120	    const present = list.some((group) =>
121	      (h.matcher == null || group.matcher === h.matcher)
122	      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
123	    if (!present) {
124	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
125	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
126	    }
127	  }
128	  if (added.length) {
129	    mkdirSync(dirname(path), { recursive: true });
130	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
131	  }
132	  return { added };
133	}
134	
135	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
136	// the repo's CLAUDE.md. Returns true when a line was removed.
137	export function removeRetiredCorpusImport(root) {
138	  const path = join(root, CLAUDE_MD);
139	  if (!existsSync(path)) return false;
140	  const text = readFileSync(path, 'utf8');
141	  if (!CORPUS_IMPORT_RE.test(text)) return false;
142	  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
143	  return true;
144	}
145	
146	// Materialize the repo's say over the badge row — `"badges": { "readme": "auto" }`
147	// — when the file does not carry it yet. The knob is written rather than defaulted
148	// so it sits visibly in the file anyone would open to change it: setting `"off"`
149	// is how a repo tells the nightly to stop maintaining (and stop re-adding) the row.
150	// Returns true when the key was added. A malformed or missing settings file is
151	// left alone — this converge never creates or repairs settings.
152	export function ensureBadgeSetting(root) {
153	  const path = join(root, CHECKS_PATH);
154	  if (!existsSync(path)) return false;
155	  const text = readFileSync(path, 'utf8');
156	  let raw;
157	  try { raw = JSON.parse(text); } catch { return false; }
158	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges !== undefined) return false;
159	  writeFileSync(path, JSON.stringify({ ...raw, badges: { readme: 'auto' } }, null, 2) + '\n');
160	  return true;
161	}
162	
163	// The row's entries: each declared pack (the `requires` closure included, in
164	// declaration order) that has a badge on disk, as { id, path } with the path
165	// relative to the repo root. Derived from the pack's own `dir`, so it resolves to
166	// `packs/<id>/…` in the canon home and `.claudinite/shared/packs/<id>/…` in a
167	// consumer with no branch on which repo this is. A pack whose badge is missing is
168	// skipped rather than reported: a repo's own local pack need not have one.
169	export async function badgeRowEntries(root, config) {
170	  const { loadPacks, resolveDeclaredPacks, packEntryId } = await import('../pack_loader/pack-registry.mjs');
171	  const packs = await loadPacks({ localRoot: root });
172	  const byId = new Map(packs.map((p) => [p.id, p]));
173	  const entries = [];
174	  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
175	    const pack = byId.get(packEntryId(entry));
176	    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
177	    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
178	    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
179	  }
180	  return entries;
181	}
182	
183	export const renderBadgeRow = (entries) =>
184	  `${BADGE_ROW_START}\n${entries.map((e) => `![${e.id}](${e.path} "${e.id}")`).join(' ')}${BADGE_ROW_END}`;
185	
186	// Write the row into the repo's README: replacing the delimited block where one
187	// exists, otherwise introducing it just under the title (a README's badges belong
188	// where a reader looks first) or at the very top when there is no heading.
189	// Returns true when the file was written. No README, or nothing to show, means
190	// nothing to do — this converge never creates a README.
191	export function convergeBadgeRow(root, entries) {
192	  const path = join(root, README);
193	  if (!existsSync(path) || !entries.length) return false;
194	  const text = readFileSync(path, 'utf8');
195	  const row = renderBadgeRow(entries);
196	  if (BADGE_ROW_RE.test(text)) {
197	    const next = text.replace(BADGE_ROW_RE, row);
198	    if (next === text) return false;
199	    writeFileSync(path, next);
200	    return true;
201	  }
202	  const lines = text.split('\n');
203	  const title = lines.findIndex((l) => l.startsWith('# '));
204	  const at = title === -1 ? 0 : title + 1;
205	  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
206	  writeFileSync(path, lines.join('\n'));
207	  return true;
208	}
209	
210	// Converge every wiring surface, returning a flat summary of what changed (empty
211	// when the repo was already converged). `stubText` is the vendored scheduler stub.
212	export async function convergeWiring(root, fullName, stubText, secretNames = []) {
213	  const changed = [];
214	  if (convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
215	  const hooks = ensureHooks(root);
216	  for (const h of hooks.added) changed.push(`hook:${h}`);
217	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
218	  if (ensureBadgeSetting(root)) changed.push(`${CHECKS_PATH} badges`);
219	  const config = await repoConfig(root);
220	  // 'off' is the repo's answer, and it means BOTH halves: stop updating the row,
221	  // and stop re-adding one the repo has deleted.
222	  if (config.badges?.readme !== 'off' && convergeBadgeRow(root, await badgeRowEntries(root, config))) changed.push(`${README} pack row`);
223	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
224	}
225	
226	// CLI: `node converge-wiring.mjs [owner/repo]` — converge THIS repo's wiring. The
227	// full name comes from argv or GITHUB_REPOSITORY/CLAUDINITE_REPO; the scheduler
228	// stub from the vendored mount. This is the single surface bootstrap (Part 6) and
229	// baselining both invoke, so the wiring set is defined once, here.
230	async function main() {
231	  const fullName = process.argv[2] || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
232	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
233	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
234	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
235	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
236	  const secretNames = await declaredSecrets(root, await repoConfig(root));
237	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames);
238	  if (error) console.log(`! ${error}`);
239	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
240	}
241	
242	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
243

