// Remove the retired `badges` setting from `.claudinite-checks.json`. The knob
// existed to tell the NIGHTLY to leave the row alone; with the nightly out of the
// README entirely there is nothing left for it to say, and every member adopted
// before this change carries it materialized. Cleaned up here — beside the retired
// corpus import, for the same reason: a converge that already runs on every member
// is where a retired setting goes to die, so no one hand-edits a file for it.
// Returns true when the key was removed. A malformed settings file is left alone.
export function removeRetiredBadgeSetting(root) {
  const path = join(root, '.claudinite-checks.json');
  if (!existsSync(path)) return false;
  let raw;
  try { raw = JSON.parse(readFileSync(path, 'utf8')); } catch { return false; }
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
  const { badges, ...rest } = raw;
  writeFileSync(path, JSON.stringify(rest, null, 2) + '\n');
  return true;
}

// The row's entries

